params.yaml:
version: 1
name: daily
actor: agent:owner:node:worker
schedule: {interval: 60}
source: {kind: taskwarrior, filter: "+ready"}
policy:
  routes: [{tag: "route:self", target: self}]
  default: self
  task_template: "{{task.description}}"
on_task_timeout: {action: escalate, escalate_to: "user:owner"}

version: 1
name: daily
launch: {harness: codex}
schedule: {interval: 60}
source: {kind: taskwarrior, filter: "+ready"}
policy:
  routes: [{tag: "route:self", target: self}]
  default: self
  task_template: "{{task.description}}"
on_task_timeout: {action: escalate, escalate_to: "user:owner"}

version: 1
name: daily
actor: agent:owner:node:worker
schedule: {interval: 60}
source: {kind: pac-journal, idle_threshold: 120}
policy:
  routes: [{tag: "route:self", target: self}]
  default: self
  task_template: "{{task.description}}"
on_task_timeout: {action: escalate, escalate_to: "user:owner"}
